	"os/exec"
	"regexp"
	"runtime"
	"strconv"
	"strings"
)

// MeasureLatency pings a specified host a user-defined number of times
// and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if host == "" {
		return 0, errors.New("host cannot be empty")
	}
	if count <= 0 {
		return 0, errors.New("count must be a positive integer")
	}

	var cmd *exec.Cmd

	// Build the ping command based on the operating system
	switch runtime.GOOS {
	case "windows":
		// Windows: ping -n <count> <host>
		cmd = exec.Command("ping", "-n", strconv.Itoa(count), host)
	case "darwin", "linux":
		// macOS/Linux: ping -c <count> <host>
		cmd = exec.Command("ping", "-c", strconv.Itoa(count), host)
	default:
		return 0, fmt.Errorf("unsupported operating system: %s", runtime.GOOS)
	}

	// Execute the command and capture output
	output, err := cmd.CombinedOutput()
	if err != nil {
		return 0, fmt.Errorf("ping command failed: %v, output: %s", err, string(output))
	}

	// Parse the output to extract average latency
	avgLatency, err := parseAverageLatency(string(output))
	if err != nil {
		return 0, fmt.Errorf("failed to parse ping output: %v", err)
	}

	return avgLatency, nil
}

// parseAverageLatency extracts the average latency from ping command output
func parseAverageLatency(output string) (float64, error) {
	// Different patterns for different operating systems
	var patterns []*regexp.Regexp

	switch runtime.GOOS {
	case "windows":
		// Windows output example: "Average = 10ms"
		patterns = []*regexp.Regexp{
			regexp.MustCompile(`Average\s*=\s*(\d+(?:\.\d+)?)\s*ms`),
			regexp.MustCompile(`平均\s*=\s*(\d+(?:\.\d+)?)\s*ms`), // Chinese Windows
		}
	case "darwin":
		// macOS output example: "round-trip min/avg/max/stddev = 10.123/15.456/20.789/3.456 ms"
		patterns = []*regexp.Regexp{
			regexp.MustCompile(`round-trip\s+min/avg/max/stddev\s*=\s*[\d.]+/([\d.]+)/[\d.]+/[\d.]+\s*ms`),
		}
	case "linux":
		// Linux output example: "rtt min/avg/max/mdev = 10.123/15.456/20.789/3.456 ms"
		patterns = []*regexp.Regexp{
			regexp.MustCompile(`rtt\s+min/avg/max/mdev\s*=\s*[\d.]+/([\d.]+)/[\d.]+/[\d.]+\s*ms`),
			regexp.MustCompile(`round-trip\s+min/avg/max/stddev\s*=\s*[\d.]+/([\d.]+)/[\d.]+/[\d.]+\s*ms`),
		}
	default:
		return 0, fmt.Errorf("unsupported operating system: %s", runtime.GOOS)
	}

	// Try each pattern
	for _, pattern := range patterns {
		matches := pattern.FindStringSubmatch(output)
		if len(matches) >= 2 {
			avgStr := strings.TrimSpace(matches[1])
			avg, err := strconv.ParseFloat(avgStr, 64)
			if err != nil {
				continue
			}
			return avg, nil
		}
	}

	return 0, errors.New("could not find average latency in ping output")
}

func main() {
	// Example usage
	host := "google.com"
	count := 4

	fmt.Printf("Measuring latency to %s with %d pings...\n", host, count)

	avgLatency, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}

