	}
	return parseUnixOutput(output)
}

// parseUnixOutput parses ping output on Linux/macOS
func parseUnixOutput(output string) (float64, error) {
	// Pattern for Linux: rtt min/avg/max/mdev = X/X/X/X ms
	// Pattern for macOS: round-trip min/avg/max/stddev = X/X/X/X ms
	patterns := []string{
		`rtt min/avg/max/mdev = [\d.]+/([\d.]+)/[\d.]+/[\d.]+ ms`,
		`round-trip min/avg/max/stddev = [\d.]+/([\d.]+)/[\d.]+/[\d.]+ ms`,
		`min/avg/max/mdev = [\d.]+/([\d.]+)/[\d.]+/[\d.]+ ms`,
	}

	for _, pattern := range patterns {
		re := regexp.MustCompile(pattern)
		matches := re.FindStringSubmatch(output)
		if len(matches) >= 2 {
			avg, err := strconv.ParseFloat(matches[1], 64)
			if err != nil {
