	return parseAverageLatency(string(output))
}

// parseAverageLatency extracts the average latency from ping output
func parseAverageLatency(output string) (float64, error) {
	// Try to parse the average from the statistics line
	// Linux/macOS format: "rtt min/avg/max/mdev = 10.123/15.456/20.789/3.456 ms"
	// Windows format: "Average = 15ms" or "Minimum = 10ms, Maximum = 20ms, Average = 15ms"

	// Try Linux/macOS format first
	// Pattern matches: min/avg/max/mdev = X.XXX/Y.YYY/Z.ZZZ/W.WWW ms
	unixPattern := regexp.MustCompile(`(?:rtt|round-trip)\s+min/avg/max/(?:mdev|stddev)\s*=\s*[\d.]+/([\d.]+)/[\d.]+/[\d.]+\s*ms`)
	matches := unixPattern.FindStringSubmatch(output)
	if len(matches) >= 2 {
		avg, err := strconv.ParseFloat(matches[1], 64)
		if err != nil {
			return 0, fmt.Errorf("failed to parse average latency: %v", err)
		}
		return avg, nil
	}

	// Try alternative Unix format (some systems use different wording)
	altUnixPattern := regexp.MustCompile(`min/avg/max\s*=\s*[\d.]+/([\d.]+)/[\d.]+\s*ms`)
	matches = altUnixPattern.FindStringSubmatch(output)
	if len(matches) >= 2 {
		avg, err := strconv.ParseFloat(matches[1], 64)
		if err != nil {
			return 0, fmt.Errorf("failed to parse average latency: %v", err)
		}
		return avg, nil
	}

	// Try Windows format
	windowsPattern := regexp.MustCompile(`Average\s*=\s*(\d+)\s*ms`)
	matches = windowsPattern.FindStringSubmatch(output)
	if len(matches) >= 2 {
		avg, err := strconv.ParseFloat(matches[1], 64)
		if err != nil {
			return 0, fmt.Errorf("failed to parse average latency: %v", err)
		}
		return avg, nil
	}

	// If we couldn't find the average in summary, try to calculate it from individual pings
	return calculateAverageFromIndividualPings(output)
}

// calculateAverageFromIndividualPings calculates average from individual ping responses
func calculateAverageFromIndividualPings(output string) (float64, error) {
	// Pattern for individual ping times
	// Linux/macOS: "time=15.4 ms" or "time=15.4ms"
	// Windows: "time=15ms" or "time<1ms"
	pattern := regexp.MustCompile(`time[=<](\d+\.?\d*)\s*ms`)
	matches := pattern.FindAllStringSubmatch(output, -1)

	if len(matches) == 0 {
		return 0, errors.New("could not parse ping output: no latency values found")
	}

	var total float64
	var count int

	for _, match := range matches {
		if len(match) >= 2 {
			latency, err := strconv.ParseFloat(match[1], 64)
			if err != nil {
				continue
			}
			total += latency
			count++
		}
	}

	if count == 0 {
		return 0, errors.New("no valid latency values found in ping output")
	}

	return total / float64(count), nil
}

func main() {
	// Example usage
	hosts := []string{"google.com", "github.com", "localhost"}
	pingCount := 4

	for _, host := range hosts {
		fmt.Printf("Measuring latency to %s (%d pings)...\n", host, pingCount)

		avgLatency, err := MeasureLatency(host, pingCount)
		if err != nil {
			fmt.Printf("  Error: %v\n", err)
			continue
		}

		fmt.Printf("  Average latency: %.2f ms\n", avgLatency)
	}

	// Demonstrate error handling
	fmt.Println("\nTesting error cases:")

	_, err := MeasureLatency("", 4)
	if err != nil {
		fmt.Printf("  Empty host error: %v\n", err)
	}

	_, err = MeasureLatency("google.com", 0)
	if err != nil {
		fmt.Printf("  Invalid count error: %v\n", err)
	}

	// Test with an invalid host
	_, err = MeasureLatency("invalid.host.that.does.not.exist.example", 1)
	if err != nil {
		// Truncate long error messages
		errStr := err.Error()
		if len(errStr) > 100 {
			errStr = errStr[:100] + "..."
		}
		// Replace newlines for cleaner output
		errStr = strings.ReplaceAll(errStr, "\n", " ")
		fmt.Printf("  Invalid host error: %s\n", errStr)
	}
}

