	// or "round-trip min/avg/max/stddev = 10.123/15.456/20.789/3.210 ms"
	unixPattern := regexp.MustCompile(`(?:rtt|round-trip)\s+min/avg/max/(?:mdev|stddev)\s*=\s*[\d.]+/([\d.]+)/[\d.]+/[\d.]+\s*ms`)
	matches := unixPattern.FindStringSubmatch(output)
	if len(matches) >= 2 {
		return strconv.ParseFloat(matches[1], 64)
	}

	// Windows format: "Average = 15ms" or "Average = 15.5ms"
	windowsPattern := regexp.MustCompile(`Average\s*=\s*([\d.]+)\s*ms`)
	matches = windowsPattern.FindStringSubmatch(output)
	if len(matches) >= 2 {
		return strconv.ParseFloat(matches[1], 64)
	}

	// Alternative Windows format (non-English): look for patterns like "15ms"
	// Try to find any average-like pattern
