import (
	"errors"
	"fmt"
	"os/exec"
	"regexp"
	"strconv"
	"strings"
)

// isValidHost checks if the host is a valid hostname or IP address
// This prevents command injection by rejecting hosts with shell metacharacters
func isValidHost(host string) bool {
	// Reject empty hosts
	if host == "" {
		return false
	}

	// Reject hosts that are too long
	if len(host) > 253 {
		return false
	}

	// Valid hostname/IP pattern: alphanumeric, dots, hyphens, and colons (for IPv6)
	// Must not contain shell metacharacters or whitespace
	validHostPattern := regexp.MustCompile(`^[a-zA-Z0-9][a-zA-Z0-9.\-:]*[a-zA-Z0-9]$|^[a-zA-Z0-9]$`)

	if !validHostPattern.MatchString(host) {
		return false
	}

	// Additional check: reject any shell metacharacters
	dangerousChars := []string{";", "&", "|", "$", "`", "(", ")", "{", "}", "[", "]", "<", ">", "!", "'", "\"", "\\", "\n", "\r", " ", "\t"}
	for _, char := range dangerousChars {
		if strings.Contains(host, char) {
			return false
		}
	}

	return true
}

// MeasureLatency pings the specified host the given number of times and returns the average latency in milliseconds.
// It uses the system 'ping' command via os/exec and parses the output to extract the average RTT.
func MeasureLatency(host string, count int) (float64, error) {
	if host == "" {
		return 0, errors.New("host cannot be empty")
	}

	if !isValidHost(host) {
		return 0, errors.New("invalid host format")
	}

	if count <= 0 {
		return 0, errors.New("count must be positive")
	}

	// Limit count to a reasonable maximum to prevent abuse
	if count > 100 {
		return 0, errors.New("count must not exceed 100")
	}

	// Execute ping directly without shell interpretation
	// This prevents command injection as arguments are passed directly to the ping executable
	countStr := strconv.Itoa(count)
	cmd := exec.Command("ping", "-c", countStr, host)

	output, err := cmd.CombinedOutput()
	if err != nil {
		return 0, fmt.Errorf("failed to execute ping: %w (output: %s)", err, string(output))
	}

	// Look for the line containing RTT statistics
	outputStr := string(output)
	lines := strings.Split(outputStr, "\n")
	var statsLine string
	for _, line := range lines {
		if strings.Contains(line, "rtt min/avg/max") || strings.Contains(line, "round-trip min/avg/max") {
			statsLine = line
			break
		}
	}

	if statsLine == "" {
		return 0, errors.New("could not find RTT statistics in ping output")
	}

	// Extract average latency using regex
	// Example line: rtt min/avg/max/mdev = 12.345/23.456/34.567/5.678 ms
	// Also handles: round-trip min/avg/max/stddev = 12.345/23.456/34.567/5.678 ms (macOS)
	re := regexp.MustCompile(`(?:rtt|round-trip) min/avg/max/(?:mdev|stddev) = [\d.]+/([\d.]+)/[\d.]+/[\d.]+ ms`)
	matches := re.FindStringSubmatch(statsLine)
	if len(matches) < 2 {
		return 0, errors.New("failed to parse average latency from ping output")
	}

	avgStr := matches[1]
	avg, err := strconv.ParseFloat(avgStr, 64)
	if err != nil {
		return 0, fmt.Errorf("failed to convert average latency to float: %w", err)
	}

	return avg, nil
}

func main() {
	// Example usage
	host := "google.com"
	count := 4

	avg, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}

	fmt.Printf("Average latency to %s: %.2f ms\n", host, avg)
}

