		}
		return avg, nil
	}

	// Try alternative Linux/macOS format (some systems use different format)
	altRttRegex := regexp.MustCompile(`min/avg/max/(?:mdev|stddev)\s*=\s*[\d.]+/([\d.]+)/[\d.]+/[\d.]+\s*ms`)
	matches = altRttRegex.FindStringSubmatch(output)
	if len(matches) >= 2 {
		avg, err := strconv.ParseFloat(matches[1], 64)
		if err != nil {
			return 0, fmt.Errorf("failed to parse average latency: %v", err)
		}
		return avg, nil
	}

