// isValidHost validates that the host is a reasonable hostname or IP address
// and doesn't contain shell metacharacters or other dangerous characters.
func isValidHost(host string) bool {
	// Check for empty or too long hosts
	if len(host) == 0 || len(host) > 253 {
		return false
	}

	// Regex pattern for valid hostname or IP address
	// Allows alphanumeric characters, dots, hyphens, and colons (for IPv6)
	// Does not allow shell metacharacters like ;, |, &, $, `, etc.
	validHostPattern := regexp.MustCompile(`^[a-zA-Z0-9][a-zA-Z0-9.\-:]*[a-zA-Z0-9]$|^[a-zA-Z0-9]$`)

	if !validHostPattern.MatchString(host) {
		return false
	}

	// Additional check: ensure no dangerous characters are present
	dangerousChars := []string{";", "|", "&", "$", "`", "(", ")", "{", "}", "[", "]", "<", ">", "!", "'", "\"", "\\", "\n", "\r", " ", "\t"}
	for _, char := range dangerousChars {
		if strings.Contains(host, char) {
			return false
		}
	}

	return true
}

// MeasureLatency pings the specified host the given number of times and returns the average latency in milliseconds.
// It uses the system 'ping' command via os/exec and parses the output to extract the average RTT.
func MeasureLatency(host string, count int) (float64, error) {
	if host == "" {
		return 0, errors.New("host cannot be empty")
	}

	// Validate host to prevent command injection
	if !isValidHost(host) {
		return 0, errors.New("invalid host: contains invalid characters")
	}

	if count <= 0 {
		return 0, errors.New("count must be positive")
	}

	// Limit count to a reasonable maximum to prevent abuse
	if count > 100 {
		return 0, errors.New("count must not exceed 100")
	}

	// Use exec.Command with separate arguments instead of bash -c
	// This prevents shell injection as arguments are passed directly to the ping command
	countStr := strconv.Itoa(count)
	cmd := exec.Command("ping", "-c", countStr, host)

	output, err := cmd.CombinedOutput()
	if err != nil {
		return 0, fmt.Errorf("failed to execute ping: %w (output: %s)", err, string(output))
	}

	// Look for the line containing RTT statistics
	outputStr := string(output)
	lines := strings.Split(outputStr, "\n")
	var statsLine string
	for _, line := range lines {
		if strings.Contains(line, "rtt min/avg/max") || strings.Contains(line, "round-trip min/avg/max") {
			statsLine = line
			break
		}
	}

	if statsLine == "" {
		return 0, errors.New("could not find RTT statistics in ping output")
	}

