// calculateAverageFromIndividualPings extracts individual ping times and calculates the average
func calculateAverageFromIndividualPings(output string) (float64, error) {
	var times []float64

	// Match patterns like "time=15.4 ms" or "time=15.4ms" or "time<1ms"
	re := regexp.MustCompile(`time[=<]([\d.]+)\s*ms`)
	matches := re.FindAllStringSubmatch(output, -1)

	for _, match := range matches {
		if len(match) >= 2 {
			t, err := strconv.ParseFloat(match[1], 64)
			if err == nil {
